<?php
namespace App\Services;
use App\Models\ImportBatch;
use App\Models\Product;
use App\Models\Prospect;
use App\Models\User;
use Illuminate\Support\Facades\Validator;
use Illuminate\Support\Str;
use PhpOffice\PhpSpreadsheet\IOFactory;
use PhpOffice\PhpSpreadsheet\Shared\Date as ExcelDate;
use RuntimeException;
class ProspectImportService {
    public const MAX_ROWS=1000;
    private array $headerMap=['nama_perusahaan'=>'company_name','perusahaan'=>'company_name','company'=>'company_name','company_name'=>'company_name','website'=>'website','kota'=>'city','city'=>'city','layanan'=>'service','service'=>'service','rute'=>'route','route'=>'route','ukuran_perusahaan'=>'company_size','company_size'=>'company_size','nama_kontak'=>'contact_name','pic'=>'contact_name','contact_name'=>'contact_name','jabatan_kontak'=>'contact_position','jabatan'=>'contact_position','contact_position'=>'contact_position','telepon_whatsapp'=>'phone','telepon_wa'=>'phone','phone'=>'phone','email'=>'email','status'=>'status','tanggal_follow_up'=>'next_follow_up_at','follow_up'=>'next_follow_up_at','sumber_nama'=>'source_name','source_name'=>'source_name','sumber_url'=>'source_url','source_url'=>'source_url','catatan'=>'notes','notes'=>'notes','email_sales'=>'assigned_sales_email','sales_email'=>'assigned_sales_email','email_account_executive'=>'assigned_sales_email','account_executive_email'=>'assigned_sales_email','email_ae'=>'assigned_sales_email','potensi_deal_rp'=>'estimated_deal_value','potensi_deal'=>'estimated_deal_value','estimated_deal_value'=>'estimated_deal_value','product_sku'=>'product_sku','sku_produk'=>'product_sku','whatsapp_opt_in'=>'whatsapp_opt_in','wa_opt_in'=>'whatsapp_opt_in'];
    public function __construct(private readonly ImportAssignmentService $assignments){}
    public function preview(string $path,int $orgId): array {$rows=$this->readRows($path);if(count($rows)>self::MAX_ROWS)throw new RuntimeException('Maksimal '.self::MAX_ROWS.' baris per import.');$out=[];foreach($rows as $i=>$row){$n=$this->normalizeRow($row);if($this->empty($n))continue;$v=Validator::make($n,$this->rules());$key=Prospect::makeCompanyKey($n['company_name']??'',$n['city']??'',$orgId);$existing=$key?Prospect::where('organization_id',$orgId)->where('company_key',$key)->first():null;$fileSales=$this->assignments->resolveFileSales($n['assigned_sales_email']??null,$orgId);$out[]=['row_number'=>$i+2,'data'=>$n,'valid'=>!$v->fails(),'errors'=>$v->errors()->all(),'duplicate'=>(bool)$existing,'existing_id'=>$existing?->id,'existing_assigned_to'=>$existing?->assigned_to,'file_sales'=>$fileSales?->only(['id','name','email']),'file_sales_warning'=>!empty($n['assigned_sales_email'])&&!$fileSales?'Email AE tidak cocok dengan akun aktif di workspace ini.':null];}return$out;}
    public function import(string $path,User $actor,ImportBatch $batch,string $duplicateMode='skip',array $assignmentOptions=['mode'=>ImportAssignmentService::MODE_FILE]): array {$org=$actor->organization_id;$preview=$this->preview($path,$org);$limit=(int)($actor->organization?->activeSubscription()?->plan?->prospect_limit??1000);$existingCount=Prospect::where('organization_id',$org)->count();$potential=collect($preview)->where('valid',true)->where('duplicate',false)->count();if($existingCount+$potential>$limit)throw new RuntimeException("Import melebihi batas prospect paket ({$limit}).");$sum=['total'=>count($preview),'imported'=>0,'updated'=>0,'skipped'=>0,'errors'=>[],'assignments'=>[],'unassigned'=>0];$rr=0;foreach($preview as$item){if(!$item['valid']){$sum['errors'][]=['row'=>$item['row_number'],'messages'=>$item['errors']];continue;}$data=$item['data'];$existing=$item['existing_id']?Prospect::where('organization_id',$org)->find($item['existing_id']):null;if($existing&&$duplicateMode==='skip'){$sum['skipped']++;continue;}$a=$this->assignments->resolve($data,$assignmentOptions,$rr,$org,$existing);$rr=$a['next_round_robin_index'];$payload=collect($data)->only(['company_name','website','city','service','route','company_size','contact_name','contact_position','phone','email','status','next_follow_up_at','source_name','source_url','notes','estimated_deal_value'])->toArray();$payload['organization_id']=$org;$payload['assigned_to']=$a['user_id'];$payload['created_by']=$existing?->created_by?:$actor->id;$payload['import_batch_id']=$batch->id;if($this->bool($data['whatsapp_opt_in']??null))$payload['whatsapp_opt_in_at']=now();if($existing){$existing->update($payload);$p=$existing->fresh();$sum['updated']++;}else{$p=Prospect::create($payload);$sum['imported']++;}$sku=$data['product_sku']??null;if($sku&&($product=Product::where('organization_id',$org)->where('sku',$sku)->first()))$p->products()->syncWithoutDetaching([$product->id=>['is_primary'=>true]]);if($p->assigned_to){$k=(string)$p->assigned_to;$sum['assignments'][$k]??=['count'=>0,'prospect_ids'=>[]];$sum['assignments'][$k]['count']++;$sum['assignments'][$k]['prospect_ids'][]=$p->id;}else$sum['unassigned']++;}return$sum;}
    private function readRows(string$p): array {$r=IOFactory::createReaderForFile($p);$r->setReadDataOnly(true);$m=$r->load($p)->getSheet(0)->toArray(null,true,true,false);if(count($m)<2)return[];$h=array_map(fn($v)=>$this->mapHeader((string)$v),$m[0]);if(!in_array('company_name',$h,true))throw new RuntimeException('Kolom Nama Perusahaan wajib ada.');$rows=[];foreach(array_slice($m,1)as$row){$a=[];foreach($h as$i=>$key)if($key!==null)$a[$key]=$row[$i]??null;$rows[]=$a;}return$rows;}
    private function mapHeader(string$h):?string{$n=Str::of($h)->lower()->ascii()->replaceMatches('/[^a-z0-9]+/','_')->trim('_')->toString();return$this->headerMap[$n]??null;}
    private function normalizeRow(array$r):array{foreach($r as$k=>$v){if(is_string($v))$r[$k]=trim($v);if(($r[$k]??null)==='')$r[$k]=null;}if(!empty($r['website'])&&!preg_match('~^https?://~i',$r['website']))$r['website']='https://'.$r['website'];$r['estimated_deal_value']=max(0,(float)($r['estimated_deal_value']??0));$r['status']=$this->status($r['status']??'baru');if(isset($r['next_follow_up_at'])&&is_numeric($r['next_follow_up_at']))try{$r['next_follow_up_at']=ExcelDate::excelToDateTimeObject((float)$r['next_follow_up_at'])->format('Y-m-d H:i:s');}catch(\Throwable){$r['next_follow_up_at']=null;}return$r;}
    private function status(mixed$v):string{$v=Str::of((string)$v)->lower()->ascii()->replaceMatches('/[^a-z0-9]+/','_')->trim('_')->toString();$a=['belum_dicek'=>'baru','baru'=>'baru','sudah_dicek'=>'diriset','diriset'=>'diriset','sudah_dihubungi'=>'dihubungi','dihubungi'=>'dihubungi','ada_balasan'=>'membalas','membalas'=>'membalas','meeting'=>'meeting','demo'=>'demo','proposal'=>'proposal','negosiasi'=>'negosiasi','deal'=>'deal','ditolak'=>'ditolak','tidak_cocok'=>'tidak_cocok'];return$a[$v]??'baru';}
    private function bool(mixed$v):bool{return in_array(strtolower(trim((string)$v)),['1','ya','yes','y','true','optin','opt-in'],true);}
    private function empty(array$r):bool{return!collect($r)->filter(fn($v)=>$v!==null&&$v!=='')->count();}
    private function rules():array{return['company_name'=>['required','string','max:255'],'website'=>['nullable','url','max:255'],'city'=>['nullable','string','max:255'],'email'=>['nullable','email','max:255'],'status'=>['required','in:'.implode(',',array_keys(Prospect::STATUSES))],'source_url'=>['nullable','url'],'assigned_sales_email'=>['nullable','email'],'estimated_deal_value'=>['nullable','numeric','min:0'],'product_sku'=>['nullable','string','max:100']];}
}
